<?php

declare(strict_types=1);

namespace App\Http\Requests\Admin;

use App\Enums\Role;
use App\Models\User;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;
use Illuminate\Validation\Rules\Password;

/**
 * Create and edit a user. The password is either generated by the system (shown once) or typed by the administrator;
 * on edit it can also be left unchanged. Administrators editing their own account may change only name and email:
 * their own password goes through Change password, which asks for the current one.
 */
final class UserRequest extends FormRequest
{
    public const GENERATE = 'generate';

    public const MANUAL = 'manual';

    public const KEEP = 'keep';

    public function authorize(): bool
    {
        return true;
    }

    protected function prepareForValidation(): void
    {
        $this->merge(['email' => mb_strtolower(trim($this->string('email')->toString()))]);

        if ($this->editingSelf()) {
            $self = $this->user();
            // Own role, station and status are never changed here; only name and email are taken from the form.
            $this->merge([
                'role' => $self instanceof User ? $self->role->value : null,
                'station_id' => $self instanceof User ? $self->station_id : null,
                'is_active' => true,
            ]);
        } elseif ($this->input('role') !== Role::Officer->value) {
            $this->merge(['station_id' => null]);
        }

        if (! $this->filled('password_mode')) {
            $this->merge(['password_mode' => $this->isCreate() ? self::GENERATE : self::KEEP]);
        }
    }

    /**
     * @return array<string, list<mixed>>
     */
    public function rules(): array
    {
        $user = $this->route('user');
        $modes = $this->isCreate() ? [self::GENERATE, self::MANUAL] : [self::KEEP, self::GENERATE, self::MANUAL];

        return [
            'name' => ['required', 'string', 'max:120'],
            'email' => ['required', 'email:rfc', 'max:190', Rule::unique('users', 'email')->ignore($user instanceof User ? $user->id : null)],
            'role' => ['required', Rule::enum(Role::class)],
            'station_id' => ['nullable', 'required_if:role,'.Role::Officer->value, 'integer', Rule::exists('stations', 'id')->where('is_active', true)],
            'is_active' => ['sometimes', 'boolean'],
            'password_mode' => ['required', Rule::in($modes), function (string $attribute, mixed $value, \Closure $fail): void {
                if ($this->editingSelf() && $value !== self::KEEP) {
                    $fail('Change your own password from the Change password page, which asks for your current password.');
                }
            }],
            'password' => ['nullable', 'required_if:password_mode,'.self::MANUAL, 'string', 'confirmed', Password::min((int) config('security.password_min_length'))->letters()->numbers()],
        ];
    }

    /**
     * @return array<string, string>
     */
    public function messages(): array
    {
        return [
            'station_id.required_if' => 'A Reporting Officer must be assigned to a station.',
            'password.required_if' => 'Type a password, or choose to generate one.',
        ];
    }

    public function isCreate(): bool
    {
        return ! $this->route('user') instanceof User;
    }

    public function editingSelf(): bool
    {
        $target = $this->route('user');

        return $target instanceof User && $target->is($this->user());
    }
}
